const eq = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const r = fetchAll(4, makeSource(2));
if (!eq(r, [0, 1, 2, 3])) { console.error("FAIL", r); process.exit(1); }
console.log("ok");
EOF

